function capturePieceState(){
  const pieces={};
  Object.keys(state).forEach(id=>{
    const q=state[id];
    pieces[id]={x:q.x,y:q.y,r:q.r,f:q.f,s:q.s};
  });
  return {pieces,selected};
}
function pieceStatesDiffer(before,after){
  const ids=Object.keys(before.pieces);
  if(ids.length!==Object.keys(after.pieces).length)return true;
  return ids.some(id=>{
    const a=before.pieces[id],b=after.pieces[id];
    return !b||Math.abs(a.x-b.x)>.01||Math.abs(a.y-b.y)>.01||
      Math.abs(a.r-b.r)>.01||a.f!==b.f||Math.abs(a.s-b.s)>.0001;
  });
}
function updateUndoButton(){
  const button=document.getElementById("undoBtn");
  if(button)button.disabled=undoHistory.length===0;
}
function clearUndoHistory(){
  undoHistory=[];
  updateUndoButton();
}
function rememberForUndo(before){
  if(!before||!pieceStatesDiffer(before,capturePieceState()))return;
  undoHistory.push(before);
  if(undoHistory.length>50)undoHistory.shift();
  updateUndoButton();
}
function undoLastOperation(){
  const previous=undoHistory.pop();
  if(!previous)return;
  clearTimeout(autoCheckTimer);
  completionAnnounced=false;
  Object.keys(previous.pieces).forEach(id=>{
    const q=state[id],saved=previous.pieces[id];
    if(!q||!saved)return;
    Object.assign(q,saved);
    tf(q.el,q);
  });
  if(selected&&state[selected])state[selected].el.classList.remove("selected");
  selected=previous.selected&&state[previous.selected]?previous.selected:null;
  if(selected){
    state[selected].el.classList.add("selected");
    pieceLayer.appendChild(state[selected].el);
  }
  updateUndoButton();
  status.className="status";
  status.textContent="ひとつ前の操作にもどしました。";
}

function roundedPolygonPath(pts,radius=3.5){
  const corners=pts.map((p,i)=>{
    const prev=pts[(i-1+pts.length)%pts.length],next=pts[(i+1)%pts.length];
    const inLen=Math.hypot(prev[0]-p[0],prev[1]-p[1])||1;
    const outLen=Math.hypot(next[0]-p[0],next[1]-p[1])||1;
    const r=Math.min(radius,inLen*.18,outLen*.18);
    return {
      before:[p[0]+(prev[0]-p[0])*r/inLen,p[1]+(prev[1]-p[1])*r/inLen],
      point:p,
      after:[p[0]+(next[0]-p[0])*r/outLen,p[1]+(next[1]-p[1])*r/outLen]
    };
  });
  let d=`M ${corners[0].after[0]} ${corners[0].after[1]}`;
  for(let i=1;i<=corners.length;i++){
    const c=corners[i%corners.length];
    d+=` L ${c.before[0]} ${c.before[1]} Q ${c.point[0]} ${c.point[1]} ${c.after[0]} ${c.after[1]}`;
  }
  return `${d} Z`;
}
function poly(pts,cls){
  const rounded=cls.split(/\s+/).includes("piece")||cls.split(/\s+/).includes("used-piece-shape");
  const e=document.createElementNS(NS,rounded?"path":"polygon");
  e.setAttribute(rounded?"d":"points",rounded?roundedPolygonPath(pts):pts.map(p=>p.join(",")).join(" "));
  e.setAttribute("class",cls);
  return e;
}
function renderGrid(){
  gridLayer.innerHTML="";
  const step=25;
  for(let x=0;x<=1000;x+=step){
    const line=document.createElementNS(NS,"line");
    line.setAttribute("x1",x);line.setAttribute("y1",0);
    line.setAttribute("x2",x);line.setAttribute("y2",700);
    line.setAttribute("class","grid-line");
    gridLayer.appendChild(line);
  }
  for(let y=0;y<=700;y+=step){
    const line=document.createElementNS(NS,"line");
    line.setAttribute("x1",0);line.setAttribute("y1",y);
    line.setAttribute("x2",1000);line.setAttribute("y2",y);
    line.setAttribute("class","grid-line");
    gridLayer.appendChild(line);
  }
}
function centroid(pts){return {x:pts.reduce((a,p)=>a+p[0],0)/pts.length,y:pts.reduce((a,p)=>a+p[1],0)/pts.length}}
function shapeCenter(id){
  if(!id||!SHAPES[id])return {x:0,y:0};
  const pts=SHAPES[id];
  const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);
  return {x:(Math.min(...xs)+Math.max(...xs))/2,y:(Math.min(...ys)+Math.max(...ys))/2};
}
function tf(el,p){
  el.setAttribute("transform",`translate(${p.x} ${p.y}) rotate(${p.r}) scale(${p.s}) scale(${p.f} 1)`)
}
function localToBoard(id,pt){
  const q=state[id],rad=q.r*Math.PI/180;
  const x=pt[0]*q.s*q.f,y=pt[1]*q.s;
  return {x:q.x+x*Math.cos(rad)-y*Math.sin(rad),y:q.y+x*Math.sin(rad)+y*Math.cos(rad)};
}
function transformedVertices(id){
  return SHAPES[id].map(v=>localToBoard(id,v));
}
function verticesForPose(id,pose){
  const rad=pose.r*Math.PI/180;
  return SHAPES[id].map(([px,py])=>{
    const x=px*pose.s*pose.f,y=py*pose.s;
    return {x:pose.x+x*Math.cos(rad)-y*Math.sin(rad),y:pose.y+x*Math.sin(rad)+y*Math.cos(rad)};
  });
}
function polygonsOverlap(a,b,tolerance=1.5){
  const axes=[];
  for(const points of [a,b]){
    for(let i=0;i<points.length;i++){
      const p=points[i],q=points[(i+1)%points.length];
      const dx=q.x-p.x,dy=q.y-p.y;
      const length=Math.hypot(dx,dy)||1;
      axes.push({x:-dy/length,y:dx/length});
    }
  }
  return axes.every(axis=>{
    const ap=a.map(p=>p.x*axis.x+p.y*axis.y);
    const bp=b.map(p=>p.x*axis.x+p.y*axis.y);
    const overlap=Math.min(Math.max(...ap),Math.max(...bp))-Math.max(Math.min(...ap),Math.min(...bp));
    return overlap>tolerance;
  });
}
function hintTargetIsClear(id){
  const target=state[id]?.target;
  if(!target)return false;
  const targetVertices=verticesForPose(id,target);
  return Object.keys(state).every(otherId=>{
    if(otherId===id)return true;
    return !polygonsOverlap(targetVertices,transformedVertices(otherId));
  });
}
function findClearPose(id,reservedVertices){
  const q=state[id];
  const centers=[
    ...scatterCenters(),
    [110,110],[300,110],[500,110],[700,110],[890,110],
    [110,300],[300,300],[500,300],[700,300],[890,300],
    [110,520],[300,520],[500,520],[700,520],[890,520]
  ];
  for(const [x,y] of centers){
    const pose=centerPoseAt(id,x,y,q.r,q.f,q.s,24);
    const vertices=verticesForPose(id,pose);
    if(polygonsOverlap(vertices,reservedVertices))continue;
    const occupied=Object.keys(state).some(otherId=>
      otherId!==id&&polygonsOverlap(vertices,transformedVertices(otherId))
    );
    if(!occupied)return pose;
  }
  return null;
}
function clearHintTarget(id){
  const targetVertices=verticesForPose(id,state[id].target);
  const blockers=Object.keys(state).filter(otherId=>
    otherId!==id&&polygonsOverlap(targetVertices,transformedVertices(otherId))
  );
  for(const blockerId of blockers){
    const pose=findClearPose(blockerId,targetVertices);
    if(!pose)return false;
    Object.assign(state[blockerId],{x:pose.x,y:pose.y,r:pose.r,f:pose.f});
    tf(state[blockerId].el,state[blockerId]);
  }
  return true;
}
function fitPoseInsideBoard(id,pose,margin=18){
  const rad=pose.r*Math.PI/180;
  const verts=SHAPES[id].map(pt=>{
    const x=pt[0]*pose.s*pose.f,y=pt[1]*pose.s;
    return {x:pose.x+x*Math.cos(rad)-y*Math.sin(rad),y:pose.y+x*Math.sin(rad)+y*Math.cos(rad)};
  });
  const minX=Math.min(...verts.map(v=>v.x)),maxX=Math.max(...verts.map(v=>v.x));
  const minY=Math.min(...verts.map(v=>v.y)),maxY=Math.max(...verts.map(v=>v.y));
  let dx=0,dy=0;
  if(minX<margin)dx=margin-minX;
  else if(maxX>1000-margin)dx=(1000-margin)-maxX;
  if(minY<margin)dy=margin-minY;
  else if(maxY>700-margin)dy=(700-margin)-maxY;
  return {...pose,x:pose.x+dx,y:pose.y+dy};
}

function centerPoseAt(id,centerX,centerY,rotation,flip,scale,margin=22){
  const rad=rotation*Math.PI/180;
  const local=SHAPES[id].map(pt=>{
    const x=pt[0]*scale*flip,y=pt[1]*scale;
    return {x:x*Math.cos(rad)-y*Math.sin(rad),y:x*Math.sin(rad)+y*Math.cos(rad)};
  });
  const minX=Math.min(...local.map(v=>v.x)),maxX=Math.max(...local.map(v=>v.x));
  const minY=Math.min(...local.map(v=>v.y)),maxY=Math.max(...local.map(v=>v.y));
  const pose={
    x:centerX-(minX+maxX)/2,
    y:centerY-(minY+maxY)/2,
    r:rotation,f:flip,s:scale
  };
  return fitPoseInsideBoard(id,pose,margin);
}
function scatterCenters(){
  // Prototype 1-3：組み立てエリア全体へ、重なりにくく平均的に配置する。
  if(pieceSizeMultiplier>=1.5){
    return [[145,145],[390,145],[635,145],[860,145],[255,495],[500,495],[745,495]];
  }
  if(pieceSizeMultiplier>=1.3){
    return [[135,135],[380,135],[625,135],[865,135],[250,505],[500,505],[750,505]];
  }
  return [[125,125],[375,125],[625,125],[875,125],[245,520],[500,520],[755,520]];
}
function edgeAngle(a,b){
  return Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI;
}
function snapToOtherPiece(id){
  const moving=state[id];
  const mv=transformedVertices(id);
  let best=null;

  for(const [otherId,other] of Object.entries(state)){
    if(otherId===id)continue;
    const ov=transformedVertices(otherId);

    // まず辺同士の吸着を探す
    for(let i=0;i<mv.length;i++){
      const a=mv[i],b=mv[(i+1)%mv.length];
      const len1=Math.hypot(b.x-a.x,b.y-a.y);
      const ang1=edgeAngle(a,b);

      for(let j=0;j<ov.length;j++){
        const c=ov[j],d=ov[(j+1)%ov.length];
        const len2=Math.hypot(d.x-c.x,d.y-c.y);
        if(Math.abs(len1-len2)>18)continue;

        const ang2=edgeAngle(c,d);
        const parallel=Math.min(angleDiff(ang1,ang2),angleDiff(ang1,ang2+180));
        if(parallel>10)continue;

        // 逆向きに重ねる（辺同士が接する）
        const dx1=d.x-a.x,dy1=d.y-a.y;
        const dx2=c.x-b.x,dy2=c.y-b.y;
        const score=Math.hypot(dx1,dy1)+Math.hypot(dx2,dy2);

        if(score<90 && (!best || score<best.score)){
          best={score,dx:(dx1+dx2)/2,dy:(dy1+dy2)/2,type:"edge"};
        }
      }
    }

    // 頂点同士の吸着
    for(const a of mv){
      for(const b of ov){
        const dist=Math.hypot(b.x-a.x,b.y-a.y);
        if(dist<34 && (!best || dist<best.score)){
          best={score:dist,dx:b.x-a.x,dy:b.y-a.y,type:"vertex"};
        }
      }
    }
  }

  if(best){
    moving.x+=best.dx;
    moving.y+=best.dy;
    tf(moving.el,moving);
    status.className="status";
    status.textContent=best.type==="edge"
      ?"ピースの辺がぴったり合いました。"
      :"ピースの頂点がぴったり合いました。";
    return true;
  }
  return false;
}
function snapToGrid(id){
  const q=state[id];
  const grid=25;
  const verts=transformedVertices(id);

  let best=null;
  for(const v of verts){
    const gx=Math.round(v.x/grid)*grid;
    const gy=Math.round(v.y/grid)*grid;
    const dx=gx-v.x;
    const dy=gy-v.y;
    const dist=Math.hypot(dx,dy);

    if(!best || dist<best.dist){
      best={dx,dy,dist};
    }
  }

  if(best){
    q.x+=best.dx;
    q.y+=best.dy;
  }

  tf(q.el,q);
  status.className="status";
  status.textContent="頂点が方眼の交点に吸着しました。";
}
function smartSnap(id){
  const q=state[id];
  const before={x:q.x,y:q.y,r:q.r,f:q.f};

  // 正解位置への吸着が最優先
  snap(id);
  if(q.x!==before.x || q.y!==before.y || q.r!==before.r || q.f!==before.f)return;

  // 次にほかのピースの辺・頂点へ吸着
  if(snapToOtherPiece(id))return;

  // 最後に格子点へ吸着
  snapToGrid(id);
}
function posePoint(q,pt){
  const rad=q.r*Math.PI/180;
  const x=pt[0]*q.s*q.f,y=pt[1]*q.s;
  return {x:q.x+x*Math.cos(rad)-y*Math.sin(rad),y:q.y+x*Math.sin(rad)+y*Math.cos(rad)};
}
function centerDistance(q){
  const a=posePoint(q,[q.c.x,q.c.y]);
  const t={...q.target,c:q.c};
  const b=posePoint(t,[q.c.x,q.c.y]);
  return Math.hypot(a.x-b.x,a.y-b.y);
}
function currentList(){return PROBLEMS.filter(p=>p.level===level).slice(0,24)}
function current(){return currentList()[index]}
function angleDiff(a,b){return Math.abs(((a-b+180)%360)-180)}
function problemScale(p){return Math.min(1,540/p.bounds[0],350/p.bounds[1])}
function targetOffset(p,s){return {x:250+(650-p.bounds[0]*s)/2,y:28+(380-p.bounds[1]*s)/2}}


