function playCompleteSound(){
  try{
    const AudioCtx=window.AudioContext||window.webkitAudioContext;
    const ctx=new AudioCtx();
    const notes=[523.25,659.25,783.99];
    notes.forEach((freq,i)=>{
      const osc=ctx.createOscillator();
      const gain=ctx.createGain();
      osc.type="sine";
      osc.frequency.value=freq;
      gain.gain.setValueAtTime(0,ctx.currentTime+i*.12);
      gain.gain.linearRampToValueAtTime(.16,ctx.currentTime+i*.12+.02);
      gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.12+.28);
      osc.connect(gain);gain.connect(ctx.destination);
      osc.start(ctx.currentTime+i*.12);
      osc.stop(ctx.currentTime+i*.12+.3);
    });
    setTimeout(()=>ctx.close(),900);
  }catch(e){}
}




function playScatterSound(){
  try{
    const AudioCtx=window.AudioContext||window.webkitAudioContext;
    const ctx=new AudioCtx();
    const now=ctx.currentTime;

    // 「バラッ」と広がる感じの、短いノイズ＋下降音。
    const duration=.34;
    const buffer=ctx.createBuffer(1,Math.floor(ctx.sampleRate*duration),ctx.sampleRate);
    const data=buffer.getChannelData(0);
    for(let i=0;i<data.length;i++){
      const t=i/data.length;
      data[i]=(Math.random()*2-1)*(1-t)*(1-t);
    }
    const noise=ctx.createBufferSource();
    noise.buffer=buffer;

    const filter=ctx.createBiquadFilter();
    filter.type="bandpass";
    filter.frequency.setValueAtTime(1800,now);
    filter.frequency.exponentialRampToValueAtTime(420,now+duration);
    filter.Q.value=.7;

    const gain=ctx.createGain();
    gain.gain.setValueAtTime(.0001,now);
    gain.gain.exponentialRampToValueAtTime(.18,now+.018);
    gain.gain.exponentialRampToValueAtTime(.001,now+duration);

    noise.connect(filter);
    filter.connect(gain);
    gain.connect(ctx.destination);
    noise.start(now);
    noise.stop(now+duration);

    const osc=ctx.createOscillator();
    const og=ctx.createGain();
    osc.type="triangle";
    osc.frequency.setValueAtTime(520,now);
    osc.frequency.exponentialRampToValueAtTime(170,now+.26);
    og.gain.setValueAtTime(.12,now);
    og.gain.exponentialRampToValueAtTime(.001,now+.28);
    osc.connect(og);
    og.connect(ctx.destination);
    osc.start(now);
    osc.stop(now+.3);

    setTimeout(()=>ctx.close(),700);
  }catch(e){}
}

function getScatterTargets(){
  return scatterCenters();
}

function scatterPieces(){
  if(scatterAnimating)return;
  scatterAnimating=true;
  started=true;
  completionAnnounced=false;
  clearTimeout(autoCheckTimer);
  playScatterSound();
  const targets=getScatterTargets();
  const rotations=[0,90,180,45,135,225,315];
  document.getElementById("startBtn").classList.remove("start-ready");
  board.classList.remove("not-started");
  status.className="status";
  status.textContent="ピースが広がっています。";

  ALL_IDS.forEach((id,i)=>{
    const q=state[id];
    if(!q)return;
    const sx=q.x,sy=q.y,sr=q.r;
    const tr=rotations[i];
    const safeTarget=centerPoseAt(id,targets[i][0],targets[i][1],tr,q.f,q.s,22);
    const tx=safeTarget.x,ty=safeTarget.y;
    const delay=i*55,duration=760;
    const begin=performance.now()+delay;

    function frame(now){
      if(now<begin){requestAnimationFrame(frame);return;}
      const t=Math.min(1,(now-begin)/duration);
      const e=1-Math.pow(1-t,3);
      q.x=sx+(tx-sx)*e;
      q.y=sy+(ty-sy)*e;
      q.r=sr+(tr-sr)*e;
      tf(q.el,q);
      if(t<1){
        requestAnimationFrame(frame);
      }else{
        q.x=tx;q.y=ty;q.r=tr;tf(q.el,q);
        if(i===ALL_IDS.length-1){
          scatterAnimating=false;
          document.getElementById("startBtn").textContent="↻ もう一度";
          status.className="status";
          status.textContent=`左の「使うピース」を見て、${current().used.length}つのピースで形を作りましょう。`;
        }
      }
    }
    requestAnimationFrame(frame);
  });
}
function restartScatter(){
  started=false;
  scatterAnimating=false;
  load();
  setTimeout(scatterPieces,180);
}

function animateToSolution(){
  const preferredOrder=["L1","L2","M","P","SQ","S1","S2"];
  const p=current();
  const used=preferredOrder.filter(id=>p.used.includes(id));
  const duration=760;
  const delayStep=620;

  status.className="status";
  status.textContent="答えを1枚ずつ組み立てています。";

  used.forEach((id,i)=>{
    const q=state[id];
    if(!q||!q.target)return;

    const start={x:q.x,y:q.y,r:q.r,f:q.f};
    const end={x:q.target.x,y:q.target.y,r:q.target.r,f:q.target.f};
    const startTime=performance.now()+i*delayStep;

    function step(now){
      if(now<startTime){
        requestAnimationFrame(step);
        return;
      }

      const t=Math.min(1,(now-startTime)/duration);
      const ease=t<0.5
        ? 4*t*t*t
        : 1-Math.pow(-2*t+2,3)/2;

      q.x=start.x+(end.x-start.x)*ease;
      q.y=start.y+(end.y-start.y)*ease;

      let dr=((end.r-start.r+540)%360)-180;
      q.r=start.r+dr*ease;

      if(t>.58) q.f=end.f;

      tf(q.el,q);

      if(t<1){
        requestAnimationFrame(step);
      }else{
        q.x=end.x;
        q.y=end.y;
        q.r=end.r;
        q.f=end.f;
        tf(q.el,q);

        // 1枚ごとに軽く吸い付く演出
        const anim=document.createElementNS(NS,"animateTransform");
        anim.setAttribute("attributeName","transform");
        anim.setAttribute("type","translate");
        anim.setAttribute("additive","sum");
        anim.setAttribute("dur","0.22s");
        anim.setAttribute("values","0 0; 0 -5; 0 0");
        anim.setAttribute("keyTimes","0;0.5;1");
        anim.setAttribute("fill","remove");
        q.el.appendChild(anim);
        anim.beginElement();
        setTimeout(()=>anim.remove(),300);

        if(i===used.length-1){
          status.className="status ok";
          status.textContent="答えの形が完成しました。";
          setTimeout(()=>celebrate(),180);
        }
      }
    }
    requestAnimationFrame(step);
  });
}

