function load(){
 clearUndoHistory();
 completionAnnounced=false;
 clearTimeout(autoCheckTimer);
 const p=current(),baseScale=Math.min(problemScale(p),1.35),s=baseScale*pieceSizeMultiplier,off=targetOffset(p,s);
 document.getElementById("title").textContent=p.name;
 document.getElementById("count").textContent=`${index+1} / ${currentList().length}`;
 const currentProblemLabel=document.getElementById("currentProblemLabel");
 if(currentProblemLabel)currentProblemLabel.textContent=p.name;
 const hintStars="★".repeat(hintLevel)+"☆".repeat(3-hintLevel);
 document.getElementById("hint").textContent=`ヒント　${hintStars}`;
 renderUsedPieces(p);
 targetLayer.innerHTML="";hintLayer.innerHTML="";pieceLayer.innerHTML="";guideLayer.innerHTML="";
 state={};selected=null;

 // お手本は青灰色のシルエットで表示
 const ts=Math.min(1.18*pieceSizeMultiplier,250/p.bounds[0],250/p.bounds[1]),tox=(320-p.bounds[0]*ts)/2,toy=(320-p.bounds[1]*ts)/2;
 const silhouette=document.createElementNS(NS,"path");
 silhouette.setAttribute("d",p.silhouette);
 silhouette.setAttribute("class","silhouette");
 silhouette.setAttribute("fill-rule","evenodd");
 silhouette.setAttribute("stroke","none");
 silhouette.setAttribute("transform",`translate(${tox} ${toy}) scale(${ts})`);
 targetLayer.appendChild(silhouette);

 // 段階的ヒント：完成図の中に正解ピースの境界を重ねる。
 if(hintLevel>0){
   const vertices=[];
   p.used.forEach(id=>{
     const pose=p.poses[id],rad=pose.r*Math.PI/180;
     SHAPES[id].forEach(([px,py])=>{
       const x=px*pose.f;
       vertices.push({
         x:pose.x+x*Math.cos(rad)-py*Math.sin(rad),
         y:pose.y+x*Math.sin(rad)+py*Math.cos(rad)
       });
     });
   });
   const minX=Math.min(...vertices.map(v=>v.x));
   const minY=Math.min(...vertices.map(v=>v.y));

   p.used.forEach(id=>{
     const pose=p.poses[id];
     const h=poly(SHAPES[id],`target-hint target-hint-${hintLevel}`);
     if(hintLevel===3)h.setAttribute("fill",COLORS[id]);
     h.setAttribute("transform",`translate(${tox-minX*ts} ${toy-minY*ts}) scale(${ts}) translate(${pose.x} ${pose.y}) rotate(${pose.r}) scale(${pose.f} 1)`);
     targetLayer.appendChild(h);
   });
 }

 renderGuide(p);

 // 毎回、全7ピースを表示
 const squareOrigin={
   x:500-100*s,
   y:350-100*s
 };
 const clusterPositions=ALL_IDS.map(()=>[squareOrigin.x,squareOrigin.y]);
 const scatterPositions=getScatterTargets();
 const positions=started?scatterPositions:clusterPositions;
 ALL_IDS.forEach((id,i)=>{
   const q=positions[i],e=poly(SHAPES[id],"piece");
   e.setAttribute("fill",COLORS[id]);e.dataset.id=id;pieceLayer.appendChild(e);

   const target=p.used.includes(id)
     ? {x:off.x+p.poses[id].x*s,y:off.y+p.poses[id].y*s,r:p.poses[id].r,f:p.poses[id].f,s:s}
     : null;

   const initialRotation=started?[0,90,0,45,135,45,0][i]:0;
   // 「はじめにもどす」では7ピースを同じ基準点に置き、元の正方形に戻す。
   // 開始後のばらばら配置だけ、各ピースの実際の外周を使って盤面内へ補正する。
   const fitted=started?centerPoseAt(id,q[0],q[1],initialRotation,1,s,22):{x:q[0],y:q[1]};
   state[id]={x:fitted.x,y:fitted.y,r:initialRotation,f:1,s:s,el:e,c:centroid(SHAPES[id]),target:target};
   tf(e,state[id]);
   e.addEventListener("pointerdown",ev=>startDrag(ev,id));
   e.addEventListener("click",()=>select(id));
 });

 // 問題切替後にも、全ピースの実際の外周を再確認して盤面内へ戻す
 requestAnimationFrame(()=>{
   ALL_IDS.forEach(id=>{
     const q=state[id];
     if(!q)return;
     const safe=fitPoseInsideBoard(id,q,24);
     q.x=safe.x;q.y=safe.y;
     tf(q.el,q);
   });
 });

 status.className="status";
 document.getElementById("startBtn").textContent=started?"↻ もう一度":"▶ はじめる";
 document.getElementById("startBtn").classList.toggle("start-ready",!started);
 board.classList.toggle("not-started",!started);
 status.textContent=started
   ? `左の「使うピース」を見て、${p.used.length}つのピースで形を作りましょう。`
   : "「はじめる」を押すと、中央の正方形が組み立てエリア全体に広がります。";
 renderProblemGrid();
}
function select(id){if(selected&&state[selected])state[selected].el.classList.remove("selected");selected=id;state[id].el.classList.add("selected");pieceLayer.appendChild(state[id].el);status.className="status";status.textContent="選んだピースを動かしたり回転したりできます。"}
function point(e){const pt=board.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;return pt.matrixTransform(board.getScreenCTM().inverse())}
function setBoardInteractionLock(on){
 document.body.classList.toggle("board-interacting",on);
}
function endBoardInteraction(){
 setBoardInteractionLock(false);
}
function startDrag(e,id){
 e.preventDefault();
 if(!started||scatterAnimating)return;
 setBoardInteractionLock(true);
 select(id);
 const p=point(e),q=state[id];
 const verts=transformedVertices(id);
 const isWoodStyle=document.body.classList.contains("piece-style-wood");
 const rotationVertices=isWoodStyle
   ? [...verts,...verts.map(v=>({x:v.x+2,y:v.y+8}))]
   : verts;
 const nearest=Math.min(...rotationVertices.map(v=>Math.hypot(p.x-v.x,p.y-v.y)));
 const center=localToBoard(id,[q.c.x,q.c.y]);
 // 見た目は変えず、指・Apple Pencil・マウスごとに回転判定を広げる。
 const baseRotateHitRadius=e.pointerType==="touch"?32:e.pointerType==="pen"?27:21;
 const rotateHitRadius=baseRotateHitRadius+(isWoodStyle?8:0);

 // 最も近い頂点が判定範囲に入ったときは回転。それ以外は移動。
 if(nearest<rotateHitRadius){
   drag={
     id,
     mode:"rotate",
     before:capturePieceState(),
     cx:center.x,
     cy:center.y,
     startAngle:Math.atan2(p.y-center.y,p.x-center.x)*180/Math.PI,
     startR:q.r
   };
   status.className="status";
   status.textContent="頂点をドラッグして回転しています。";
 }else{
   drag={id,mode:"move",dx:p.x-q.x,dy:p.y-q.y,before:capturePieceState()};
   status.className="status";
   status.textContent="ピースを移動しています。";
 }
 q.el.setPointerCapture(e.pointerId);
}
board.addEventListener("pointermove",e=>{
 if(!drag)return;
 e.preventDefault();
 const p=point(e),q=state[drag.id];
 if(drag.mode==="move"){
   q.x=p.x-drag.dx;q.y=p.y-drag.dy;
 }else{
   const a=Math.atan2(p.y-drag.cy,p.x-drag.cx)*180/Math.PI;
   q.r=(drag.startR+(a-drag.startAngle)+360)%360;
   const rad=q.r*Math.PI/180;
   const lx=q.c.x*q.s*q.f,ly=q.c.y*q.s;
   q.x=drag.cx-(lx*Math.cos(rad)-ly*Math.sin(rad));
   q.y=drag.cy-(lx*Math.sin(rad)+ly*Math.cos(rad));
 }
 tf(q.el,q);
},{passive:false});
board.addEventListener("pointerup",()=>{
 if(drag){
   const before=drag.before;
   const q=state[drag.id];
   if(drag.mode==="rotate"){
     q.r=Math.round(q.r/45)*45%360;
     const rad=q.r*Math.PI/180;
     const lx=q.c.x*q.s*q.f,ly=q.c.y*q.s;
     q.x=drag.cx-(lx*Math.cos(rad)-ly*Math.sin(rad));
     q.y=drag.cy-(lx*Math.sin(rad)+ly*Math.cos(rad));
   }
   tf(q.el,q);
   smartSnap(drag.id);
   drag=null;
   rememberForUndo(before);
   scheduleAutoCheck();
 }
 endBoardInteraction();
});
board.addEventListener("pointercancel",e=>{
  drag=null;
  endBoardInteraction();
  touchPoints.delete(e.pointerId);
  if(touchPoints.size<2)gesture=null;
});
board.addEventListener("pointerdown",e=>{
  if(e.pointerType==="touch"){
    e.preventDefault();
    setBoardInteractionLock(true);
    const id=e.target?.dataset?.id||selected;
    touchPoints.set(e.pointerId,{x:e.clientX,y:e.clientY,id});
    if(touchPoints.size===2)beginGesture();
  }
},{passive:false});
board.addEventListener("pointermove",e=>{
  if(e.pointerType!=="touch"||!touchPoints.has(e.pointerId))return;
  const old=touchPoints.get(e.pointerId);
  touchPoints.set(e.pointerId,{...old,x:e.clientX,y:e.clientY});
  if(gesture&&touchPoints.size===2){
    e.preventDefault();
    const pts=[...touchPoints.values()];
    const q=state[gesture.id];
    const a=angleBetween(pts[0],pts[1]);
    q.r=(gesture.startR+(a-gesture.startAngle)+360)%360;
    const rad=q.r*Math.PI/180;
    const lx=q.c.x*q.s*q.f,ly=q.c.y*q.s;
    q.x=gesture.cx-(lx*Math.cos(rad)-ly*Math.sin(rad));
    q.y=gesture.cy-(lx*Math.sin(rad)+ly*Math.cos(rad));
    tf(q.el,q);
  }
},{passive:false});
board.addEventListener("pointerup",e=>{
  if(e.pointerType==="touch"){
    touchPoints.delete(e.pointerId);
    if(gesture&&touchPoints.size<2){
      const before=gesture.before;
      const q=state[gesture.id];
      q.r=Math.round(q.r/45)*45%360;
      const rad=q.r*Math.PI/180;
      const lx=q.c.x*q.s*q.f,ly=q.c.y*q.s;
      q.x=gesture.cx-(lx*Math.cos(rad)-ly*Math.sin(rad));
      q.y=gesture.cy-(lx*Math.sin(rad)+ly*Math.cos(rad));
      tf(q.el,q);
      smartSnap(gesture.id);
      gesture=null;
      rememberForUndo(before);
      scheduleAutoCheck();
    }
    if(touchPoints.size===0&&!drag)endBoardInteraction();
  }
});

