const rightBtn=document.getElementById("right"); if(rightBtn) rightBtn.onclick=()=>rotate(45);
const flipBtn=document.getElementById("flip"); if(flipBtn) flipBtn.onclick=()=>{
  if(!selected){
    warn("先にピースを選んでください。");
    return;
  }
  if(selected!=="P"){
    return;
  }
  const undoBefore=capturePieceState();
  const q=state[selected];
  const before=posePoint(q,[q.c.x,q.c.y]);
  q.f*=-1;
  const after=posePoint(q,[q.c.x,q.c.y]);
  q.x+=before.x-after.x;
  q.y+=before.y-after.y;
  tf(q.el,q);
  snap(selected);
  rememberForUndo(undoBefore);
  scheduleAutoCheck();
};
